#include <gtest/gtest.h>

import std;

import int3;
import double3;
import double3x3;
import skpointgroup;
import skrotationmatrix;
import skspacegroup;
import skspacegroupsetting;
import skspacegroupdatabase;
import sksymmetrycell;

// The structures in testdata/spacegroups are generated by generate_symmetrykit_testdata: for every Hall setting,
// random general positions in a cell of the setting's crystal family, so that each structure has exactly the
// symmetry of the setting it was made from (some with atoms on special positions, some with noisy coordinates to
// be identified at a looser precision). These tests read them back and check what the symmetry search makes of
// them: the space group and point group (with and without partial occupancies allowed), the smallest primitive
// cell, the Delaunay reduction, the transformation back to the original cell, and the primitive and Niggli cells
// with their atoms.

namespace
{
struct GeneratedStructure
{
  std::filesystem::path file;
  std::size_t spaceGroupNumber{};
  std::size_t hallNumber{};
  std::size_t pointGroupNumber{};
  double3x3 cell;
  std::vector<std::tuple<double3, std::size_t, double>> atoms;
  double precision{1.0e-5};  // the symmetry precision to identify the structure at [Angstrom]
  double lengthTolerance{};  // for comparing cell vectors: tight for exact structures, loose for noisy ones
  double volumeTolerance{};  // for comparing volume ratios and rotation matrices
};

// reads the few CIF items the generator writes (no general CIF parsing)
GeneratedStructure readGeneratedCIF(const std::filesystem::path& path)
{
  GeneratedStructure structure{};
  structure.file = path;
  std::ifstream file(path);
  std::string line;
  double a = 0.0, b = 0.0, c = 0.0, alpha = 90.0, beta = 90.0, gamma = 90.0;
  std::map<std::string, std::size_t> types;
  bool inAtomLoop = false;
  while (std::getline(file, line))
  {
    std::istringstream stream(line);
    std::string tag;
    stream >> tag;
    if (tag.empty() || tag[0] == '#') continue;
    if (tag == "loop_")
    {
      inAtomLoop = false;
      continue;
    }
    if (tag == "_atom_site_occupancy")
    {
      inAtomLoop = true;  // the last column header of the atom loop
      continue;
    }
    if (tag[0] == '_')
    {
      if (tag == "_raspa_hall_number") stream >> structure.hallNumber;
      if (tag == "_raspa_symmetry_precision") stream >> structure.precision;
      if (tag == "_raspa_point_group_number") stream >> structure.pointGroupNumber;
      if (tag == "_space_group_IT_number") stream >> structure.spaceGroupNumber;
      if (tag == "_cell_length_a") stream >> a;
      if (tag == "_cell_length_b") stream >> b;
      if (tag == "_cell_length_c") stream >> c;
      if (tag == "_cell_angle_alpha") stream >> alpha;
      if (tag == "_cell_angle_beta") stream >> beta;
      if (tag == "_cell_angle_gamma") stream >> gamma;
      continue;
    }
    if (inAtomLoop)
    {
      std::string symbol;
      double x, y, z, occupancy;
      stream >> symbol >> x >> y >> z >> occupancy;
      const auto [it, inserted] = types.emplace(symbol, types.size());
      structure.atoms.emplace_back(double3(x, y, z), it->second, occupancy);
    }
  }
  structure.cell = SKSymmetryCell(a, b, c, alpha, beta, gamma).unitCell();
  const bool noisy = structure.precision > 1.0e-4;
  structure.lengthTolerance = noisy ? 10.0 * structure.precision : 1.0e-5;
  structure.volumeTolerance = noisy ? 0.02 : 1.0e-6;
  return structure;
}

// the generated structures of the space groups in [first, last], in a fixed order
std::vector<GeneratedStructure> generatedStructures(std::size_t first, std::size_t last)
{
  std::vector<GeneratedStructure> structures;
  for (std::size_t number = first; number <= last; ++number)
  {
    const std::filesystem::path directory =
        std::filesystem::path("testdata/spacegroups") / std::format("{:03}", number);
    if (!std::filesystem::exists(directory)) continue;
    std::vector<std::filesystem::path> files;
    for (const auto& entry : std::filesystem::directory_iterator(directory))
      if (entry.path().extension() == ".cif") files.push_back(entry.path());
    std::sort(files.begin(), files.end());
    for (const std::filesystem::path& file : files) structures.push_back(readGeneratedCIF(file));
  }
  EXPECT_GT(structures.size(), 0uz) << "no generated structures for groups " << first << " to " << last
                                    << " (run generate_symmetrykit_testdata)";
  return structures;
}

// the atoms shifted by a random vector: the origin is not where the setting puts it
std::vector<std::tuple<double3, std::size_t, double>> shifted(const GeneratedStructure& structure, std::mt19937& rng)
{
  std::uniform_real_distribution<double> shift(-0.5, 0.5);
  const double3 randomShift(shift(rng), shift(rng), shift(rng));
  std::vector<std::tuple<double3, std::size_t, double>> atoms;
  for (const auto& [position, type, occupancy] : structure.atoms)
    atoms.emplace_back(position + randomShift, type, occupancy);
  return atoms;
}

// the atoms of the least-occurring type, which the searches start from
std::vector<std::tuple<double3, std::size_t, double>> leastOccurring(
    const std::vector<std::tuple<double3, std::size_t, double>>& atoms)
{
  std::map<std::size_t, std::size_t> histogram;
  for (const auto& atom : atoms) ++histogram[std::get<1>(atom)];
  const std::size_t type = std::min_element(histogram.begin(), histogram.end(),
                                            [](const auto& l, const auto& r) { return l.second < r.second; })
                               ->first;
  std::vector<std::tuple<double3, std::size_t, double>> reduced;
  std::copy_if(atoms.begin(), atoms.end(), std::back_inserter(reduced),
               [type](const auto& atom) { return std::get<1>(atom) == type; });
  return reduced;
}

// every structure is identified as its space group and point group, with and without partial occupancies allowed
void checkGroups(std::size_t first, std::size_t last)
{
  std::mt19937 rng(12345);
  for (const GeneratedStructure& structure : generatedStructures(first, last))
  {
    ASSERT_GE(structure.spaceGroupNumber, first) << structure.file;
    ASSERT_FALSE(structure.atoms.empty()) << structure.file;
    const auto atoms = shifted(structure, rng);
    for (const bool allowPartialOccupancies : {false, true})
    {
      const std::optional<SKSpaceGroup::FoundSpaceGroupInfo> found =
          SKSpaceGroup::findSpaceGroup(structure.cell, atoms, allowPartialOccupancies, structure.precision);
      ASSERT_TRUE(found.has_value()) << structure.file << " partial " << allowPartialOccupancies;
      EXPECT_EQ(SKSpaceGroup(found->HallNumber).spaceGroupSetting().number(), structure.spaceGroupNumber)
          << structure.file << " partial " << allowPartialOccupancies;

      const std::optional<SKPointGroup> pointGroup =
          SKSpaceGroup::findPointGroup(structure.cell, atoms, allowPartialOccupancies, structure.precision);
      ASSERT_TRUE(pointGroup.has_value()) << structure.file;
      EXPECT_EQ(pointGroup->number(), structure.pointGroupNumber) << structure.file;
    }
  }
}

// the smallest primitive cell has the volume of the conventional cell over the centring translations, its vectors
// are translations of the structure, and the Delaunay reduction keeps the volume
void checkPrimitiveCells(std::size_t first, std::size_t last)
{
  std::mt19937 rng(23456);
  for (const GeneratedStructure& structure : generatedStructures(first, last))
  {
    const auto atoms = shifted(structure, rng);
    const SKSpaceGroupSetting& setting = SKSpaceGroupDataBase::spaceGroupData[structure.hallNumber];
    const double expectedVolume =
        std::fabs(structure.cell.determinant()) / double(setting.latticeTranslations().size());
    for (const bool allowPartialOccupancies : {false, true})
    {
      const double3x3 primitive =
          SKSymmetryCell::findSmallestPrimitiveCell(allowPartialOccupancies ? atoms : leastOccurring(atoms), atoms,
                                                    structure.cell, allowPartialOccupancies, structure.precision);
      EXPECT_NEAR(std::fabs(primitive.determinant()) / expectedVolume, 1.0, structure.volumeTolerance)
          << structure.file << " partial " << allowPartialOccupancies;
      for (std::size_t i = 0; i < 3; ++i)
      {
        const double3 translation = structure.cell.inverse() * primitive[i];
        EXPECT_TRUE(SKSymmetryCell::testTranslationalSymmetry(translation, atoms, structure.cell,
                                                              allowPartialOccupancies, structure.precision))
            << structure.file << " vector " << i;
      }
      const std::optional<double3x3> delaunay =
          SKSymmetryCell::computeDelaunayReducedCell(primitive, structure.precision);
      ASSERT_TRUE(delaunay.has_value()) << structure.file;
      EXPECT_NEAR(std::fabs(delaunay->determinant()) / expectedVolume, 1.0, structure.volumeTolerance)
          << structure.file;
      EXPECT_GT(delaunay->determinant(), 0.0) << structure.file;  // right-handed
    }
  }
}

// the found conventional cell, rotation and transformation reproduce the original cell, and the rotation is proper
void checkTransformations(std::size_t first, std::size_t last)
{
  std::mt19937 rng(34567);
  for (const GeneratedStructure& structure : generatedStructures(first, last))
  {
    const auto atoms = shifted(structure, rng);
    const std::optional<SKSpaceGroup::FoundSpaceGroupInfo> found =
        SKSpaceGroup::findSpaceGroup(structure.cell, atoms, false, structure.precision);
    ASSERT_TRUE(found.has_value()) << structure.file;
    const double3x3 reconstructed = found->rotationMatrix * found->cell.unitCell() * found->transformationMatrix;
    for (std::size_t i = 0; i < 3; ++i)
      for (std::size_t j = 0; j < 3; ++j)
        EXPECT_NEAR(reconstructed[i][j], structure.cell[i][j], structure.lengthTolerance)
            << structure.file << " " << i << " " << j;
    EXPECT_NEAR(found->rotationMatrix.determinant(), 1.0, structure.volumeTolerance) << structure.file;
    const double3x3 orthogonality = found->rotationMatrix.transpose() * found->rotationMatrix;
    for (std::size_t i = 0; i < 3; ++i)
      for (std::size_t j = 0; j < 3; ++j)
        EXPECT_NEAR(orthogonality[i][j], i == j ? 1.0 : 0.0, structure.volumeTolerance) << structure.file;
  }
}

// the number of atoms of each type
std::map<std::size_t, std::size_t> histogram(const std::vector<std::tuple<double3, std::size_t, double>>& atoms)
{
  std::map<std::size_t, std::size_t> counts;
  for (const auto& atom : atoms) ++counts[std::get<1>(atom)];
  return counts;
}

// the primitive cell of a structure holds one lattice point, so the conventional volume and every type count over
// the number of centring translations, and still has the symmetry of the group
void checkFindPrimitive(std::size_t first, std::size_t last)
{
  std::mt19937 rng(56789);
  for (const GeneratedStructure& structure : generatedStructures(first, last))
  {
    const auto atoms = shifted(structure, rng);
    const SKSpaceGroupSetting& setting = SKSpaceGroupDataBase::spaceGroupData[structure.hallNumber];
    const std::size_t latticePoints = setting.latticeTranslations().size();
    for (const bool allowPartialOccupancies : {false, true})
    {
      const std::optional<SKSpaceGroup::FoundPrimitiveCellInfo> primitive =
          SKSpaceGroup::SKFindPrimitive(structure.cell, atoms, allowPartialOccupancies, structure.precision);
      ASSERT_TRUE(primitive.has_value()) << structure.file << " partial " << allowPartialOccupancies;
      EXPECT_NEAR(std::fabs(primitive->cell.unitCell().determinant()) * double(latticePoints) /
                      std::fabs(structure.cell.determinant()),
                  1.0, structure.volumeTolerance)
          << structure.file << " partial " << allowPartialOccupancies;
      ASSERT_EQ(primitive->atoms.size() * latticePoints, atoms.size())
          << structure.file << " partial " << allowPartialOccupancies;
      for (const auto& [type, count] : histogram(atoms))
        EXPECT_EQ(histogram(primitive->atoms)[type] * latticePoints, count) << structure.file << " type " << type;

      const std::optional<SKSpaceGroup::FoundSpaceGroupInfo> found = SKSpaceGroup::findSpaceGroup(
          primitive->cell.unitCell(), primitive->atoms, allowPartialOccupancies, structure.precision);
      ASSERT_TRUE(found.has_value()) << structure.file << " partial " << allowPartialOccupancies;
      EXPECT_EQ(SKSpaceGroup(found->HallNumber).spaceGroupSetting().number(), structure.spaceGroupNumber)
          << structure.file << " partial " << allowPartialOccupancies;
    }
  }
}

// the Niggli search identifies the group of the structure through its reduced primitive cell and returns the
// conventional cell of the setting it found (the same primitive volume as the input) with one asymmetric atom per
// orbit, which here is one per element
void checkNiggliCells(std::size_t first, std::size_t last)
{
  std::mt19937 rng(67890);
  for (const GeneratedStructure& structure : generatedStructures(first, last))
  {
    const auto atoms = shifted(structure, rng);
    const SKSpaceGroupSetting& setting = SKSpaceGroupDataBase::spaceGroupData[structure.hallNumber];
    const double primitiveVolume =
        std::fabs(structure.cell.determinant()) / double(setting.latticeTranslations().size());
    for (const bool allowPartialOccupancies : {false, true})
    {
      const std::optional<SKSpaceGroup::FoundNiggliCellInfo> niggli =
          SKSpaceGroup::findNiggliCell(structure.cell, atoms, allowPartialOccupancies, structure.precision);
      ASSERT_TRUE(niggli.has_value()) << structure.file << " partial " << allowPartialOccupancies;
      const SKSpaceGroupSetting& foundSetting = SKSpaceGroupDataBase::spaceGroupData[niggli->HallNumber];
      EXPECT_EQ(foundSetting.number(), structure.spaceGroupNumber)
          << structure.file << " partial " << allowPartialOccupancies;
      EXPECT_NEAR(std::fabs(niggli->cell.unitCell().determinant()) /
                      (primitiveVolume * double(foundSetting.latticeTranslations().size())),
                  1.0, structure.volumeTolerance)
          << structure.file << " partial " << allowPartialOccupancies;
      EXPECT_EQ(niggli->atoms.size(), histogram(atoms).size())
          << structure.file << " partial " << allowPartialOccupancies;
    }
  }
}

// a random proper rotation of the Cartesian frame (Rodrigues' formula about a random axis)
double3x3 randomRotation(std::mt19937& rng)
{
  std::uniform_real_distribution<double> unit(-1.0, 1.0);
  std::uniform_real_distribution<double> angle(0.0, 2.0 * std::numbers::pi);
  double3 axis(unit(rng), unit(rng), unit(rng));
  axis = axis / axis.length();
  const double theta = angle(rng);
  const double c = std::cos(theta), s = std::sin(theta), t = 1.0 - c;
  return double3x3(
      double3(c + t * axis.x * axis.x, t * axis.x * axis.y + s * axis.z, t * axis.x * axis.z - s * axis.y),
      double3(t * axis.x * axis.y - s * axis.z, c + t * axis.y * axis.y, t * axis.y * axis.z + s * axis.x),
      double3(t * axis.x * axis.z + s * axis.y, t * axis.y * axis.z - s * axis.x, c + t * axis.z * axis.z));
}

// a random integer basis change of determinant +1 or -1: a product of elementary shears and a possible axis swap
double3x3 randomUnimodular(std::mt19937& rng)
{
  std::uniform_int_distribution<int> shear(-2, 2);
  std::uniform_int_distribution<std::size_t> index(0, 2);
  std::uniform_int_distribution<int> coin(0, 1);
  double3x3 matrix = double3x3::identity();
  for (int step = 0; step < 4; ++step)
  {
    std::size_t from = index(rng), to = index(rng);
    if (from == to) continue;
    double3x3 elementary = double3x3::identity();
    elementary[to][from] = double(shear(rng));  // column 'to' gains a multiple of axis 'from'
    matrix = matrix * elementary;
  }
  if (coin(rng))  // a mirror: the left-handed cell has to work too
  {
    std::swap(matrix[0], matrix[1]);
  }
  return matrix;
}

// the structure in a rotated frame, in a skewed (possibly left-handed) basis, and as a supercell: the group, the
// primitive volume and the reconstruction of the input cell from the result do not depend on the presentation
void checkArbitraryBases(std::size_t first, std::size_t last)
{
  std::mt19937 rng(78901);
  std::uniform_int_distribution<std::size_t> doubledAxis(0, 2);
  for (const GeneratedStructure& structure : generatedStructures(first, last))
  {
    const auto atoms = shifted(structure, rng);
    const SKSpaceGroupSetting& setting = SKSpaceGroupDataBase::spaceGroupData[structure.hallNumber];
    const double primitiveVolume =
        std::fabs(structure.cell.determinant()) / double(setting.latticeTranslations().size());

    // rotated frame: the fractional coordinates are unchanged
    const double3x3 rotated = randomRotation(rng) * structure.cell;

    // skewed basis: the coordinates follow the inverse basis change
    const double3x3 unimodular = randomUnimodular(rng);
    const double3x3 skewed = structure.cell * unimodular;
    std::vector<std::tuple<double3, std::size_t, double>> skewedAtoms;
    for (const auto& [position, type, occupancy] : atoms)
      skewedAtoms.emplace_back(unimodular.inverse() * position, type, occupancy);

    // supercell: one random axis doubled, the atoms repeated along it
    int3 n(1, 1, 1);
    n[int(doubledAxis(rng))] = 2;
    const double3x3 supercell(structure.cell[0] * double(n.x), structure.cell[1] * double(n.y),
                              structure.cell[2] * double(n.z));
    std::vector<std::tuple<double3, std::size_t, double>> supercellAtoms;
    for (const auto& [position, type, occupancy] : atoms)
      for (int i = 0; i < n.x; ++i)
        for (int j = 0; j < n.y; ++j)
          for (int k = 0; k < n.z; ++k)
            supercellAtoms.emplace_back(
                double3((position.x + double(i)) / double(n.x), (position.y + double(j)) / double(n.y),
                        (position.z + double(k)) / double(n.z)),
                type, occupancy);

    const std::array<std::tuple<const char*, double3x3, const std::vector<std::tuple<double3, std::size_t, double>>*>,
                     3>
        presentations{std::tuple{"rotated", rotated, &atoms}, std::tuple{"skewed", skewed, &skewedAtoms},
                      std::tuple{"supercell", supercell, &supercellAtoms}};
    for (const auto& [name, cell, cellAtoms] : presentations)
    {
      const std::optional<SKSpaceGroup::FoundSpaceGroupInfo> found =
          SKSpaceGroup::findSpaceGroup(cell, *cellAtoms, false, structure.precision);
      ASSERT_TRUE(found.has_value()) << structure.file << " " << name;
      EXPECT_EQ(SKSpaceGroup(found->HallNumber).spaceGroupSetting().number(), structure.spaceGroupNumber)
          << structure.file << " " << name;
      const SKSpaceGroupSetting& foundSetting = SKSpaceGroupDataBase::spaceGroupData[found->HallNumber];
      EXPECT_NEAR(std::fabs(found->cell.unitCell().determinant()) /
                      (primitiveVolume * double(foundSetting.latticeTranslations().size())),
                  1.0, structure.volumeTolerance)
          << structure.file << " " << name;
      const double3x3 reconstructed = found->rotationMatrix * found->cell.unitCell() * found->transformationMatrix;
      for (std::size_t i = 0; i < 3; ++i)
        for (std::size_t j = 0; j < 3; ++j)
          EXPECT_NEAR(reconstructed[i][j], cell[i][j],
                      structure.lengthTolerance * std::fabs(cell.determinant()) / primitiveVolume)
              << structure.file << " " << name << " " << i << " " << j;

      const std::optional<SKPointGroup> pointGroup =
          SKSpaceGroup::findPointGroup(cell, *cellAtoms, false, structure.precision);
      ASSERT_TRUE(pointGroup.has_value()) << structure.file << " " << name;
      EXPECT_EQ(pointGroup->number(), structure.pointGroupNumber) << structure.file << " " << name;
    }
  }
}
}  // namespace

