// A conventional cell holding several lattice points: the smallest primitive cell is smaller than the conventional
// one, the symmetry test on fractional coordinates has to use the primitive lattice, and the point group is found.
TEST(GeneratedSymmetryMetric, CentredConventionalCells)
{
  std::mt19937 rng(45678);
  for (const std::size_t number : {225uz, 139uz, 70uz, 15uz})  // F, I, F and C centred
  {
    const std::vector<GeneratedStructure> structures = generatedStructures(number, number);
    ASSERT_FALSE(structures.empty());
    const GeneratedStructure& structure = structures.front();
    const auto atoms = shifted(structure, rng);
    const double3x3 primitive = SKSymmetryCell::findSmallestPrimitiveCell(leastOccurring(atoms), atoms, structure.cell,
                                                                          false, structure.precision);
    const std::optional<double3x3> delaunay =
        SKSymmetryCell::computeDelaunayReducedCell(primitive, structure.precision);
    ASSERT_TRUE(delaunay.has_value()) << structure.file;
    EXPECT_LT(std::fabs(delaunay->determinant()), std::fabs(structure.cell.determinant()) - 1.0) << structure.file;

    // a translation of the primitive lattice is a symmetry in that lattice but not a lattice vector of the
    // conventional cell
    const double3 translation = structure.cell.inverse() * (*delaunay)[0];
    std::vector<std::tuple<double3, std::size_t, double>> singleAtom{atoms.front()};
    EXPECT_TRUE(SKSymmetryCell::testSymmetry((*delaunay).inverse() * structure.cell * translation,
                                             SKRotationMatrix::identity, singleAtom, *delaunay, false,
                                             structure.precision))
        << structure.file;
    EXPECT_FALSE(SKSymmetryCell::testSymmetry(translation, SKRotationMatrix::identity, singleAtom, structure.cell,
                                              false, structure.precision))
        << structure.file;

    const std::optional<SKPointGroup> pointGroup =
        SKSpaceGroup::findPointGroup(structure.cell, atoms, false, structure.precision);
    ASSERT_TRUE(pointGroup.has_value()) << structure.file;
    EXPECT_EQ(pointGroup->number(), structure.pointGroupNumber) << structure.file;
  }
}
